for product in ['CoachForce.json', 'PersonalizeForce.json', 'SearchForce.json', 'SummarizeForce.json']:
    with open(product) as f:
        data = json.load(f)

    print(f"\n=== {product} ===")
    for d in data.get('documents', []):
        if 'Market Research Report' in d.get('type', ''):
            print(f"  Doc: {d.get('id')} author={d.get('author')}")
            if 'feedback' in d:
                # check feedback structure
                fb = d['feedback']
                print(f"    feedback type: {type(fb).__name__}")
                if isinstance(fb, list):
                    print(f"    feedback items: {len(fb)}")
                else:
                    print(f"    feedback: {fb[:300]}")

    # Look for meeting transcripts about Market Research Report
    for m in data.get('meeting_transcripts', []):
        if m.get('document_type') == 'Market Research Report':
            print(f"  Meeting: {m.get('id')} participants={m.get('participants')}")
